def largestComponentSize(nums):
    """port this code to python:
```kotlin
import java.util.*

fun largestComponentSize(nums: IntArray): Int {
    fun primes(n: Int): Int {
        for (i in 2..(n.toDouble().pow(0.5) + 1).toInt()) {
            if (n % i == 0) {
                return i
            }
        }
        return n
    }

    fun dfs(node: Int, visited: MutableSet<Int>, graph: MutableMap<Int, MutableSet<Int>>): Int {
        if (visited.contains(node)) {
            return 0
        }
        visited.add(node)
        var size = 1
        for (neighbor in graph[node]!!) {
            size += dfs(neighbor, visited, graph)
        }
        return size
    }

    val graph: MutableMap<Int, MutableSet<Int>> = HashMap()
    val visited: MutableSet<Int> = HashSet()

    for (num in nums) {
        val prime = primes(num)
        graph.computeIfAbsent(prime) { HashSet() }.add(num)
        if (num != prime) {
            graph.computeIfAbsent(num) { HashSet() }.add(prime)
        }
    }

    var count = 0
    for (num in nums) {
        count = maxOf(count, dfs(num, visited, graph))
    }

    return count
}
