def is_perfect(n):
    """Design an algorithm that segregates prime, composite and perfect numbers from a provided set of integers, also compute their sum for each category separately. Furthermore, the code should be optimized to handle bigger inputs in a time efficient manner.
[10, 11, 12, 13, 14, 15, 28, 496]"""
    sum_div = 1
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        elif i * (n // i) == n:
            sum_div = sum_div + i + n//i
            i += 1
    return sum_div == n and n!=1

